// Typed HTTP client for the backend. The types come from `src/api/schema.d.ts`, generated by
// `pnpm gen:api`; CI fails when they are stale, so a backend change that breaks the UI is a
// type error here rather than a runtime surprise.
import createClient, { type Client } from "openapi-fetch";

import type { components, paths } from "../../api/schema";

export type ApiClient = Client<paths>;
export type ErrorResponse = components["schemas"]["ErrorResponse"];

export interface ApiClientOptions {
  baseUrl: string;
  token: string;
  fetch?: (request: Request) => Promise<Response>;
}

export function createApiClient({ baseUrl, token, fetch }: ApiClientOptions): ApiClient {
  const client = createClient<paths>({ baseUrl, ...(fetch ? { fetch } : {}) });
  client.use({
    onRequest({ request }) {
      request.headers.set("Authorization", `Bearer ${token}`);
      return request;
    },
  });
  return client;
}

/** The backend's error body: `{"error": {"code": "...", "params": {...}}}` (an i18n key). */
export function isApiError(value: unknown): value is ErrorResponse {
  if (typeof value !== "object" || value === null || !("error" in value)) return false;
  const { error } = value;
  return (
    typeof error === "object" && error !== null && "code" in error && typeof error.code === "string"
  );
}
